def mutants_from_output() -> list[dict[str, str]]:
    found = []
    for line in MUT_OUT.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^(KILLED|SURVIVED) (\S+?): (.*) -> (.*)$", line)
        if not m:
            continue
        status, name, description, killed = m.groups()
        found.append({"name": name, "description": description,
                      "killed_by": killed if status == "KILLED" else None})
    return found


def build_rows() -> list[dict[str, str]]:
    # Rows that are carried or mixed, not re-written as fresh text.
    for key in ("d1-cards-math", "d1-cards-lesson-statements", "d1-cards-forward-reference", "d7-L03-numerics", "d8-2.6-symmetry-tiny-scale"):
        FRESH.pop(key, None)
    rows = []
    for r9 in R9["rows"]:
        rid = r9["id"]
        check = r9["check"]
        location = r9["location"]
        if rid in FRESH:
            value = FRESH[rid]
            status, evidence = value[0], value[1]
            row = {"id": rid, "check": check, "location": location, "status": status, "evidence": evidence}
            if status != "PASS":
                row["fix"] = value[2]
            rows.append(row)
            continue
        if rid in CARRY_FILES:
            evidence = CARRY_PREFIX % CARRY_FILES[rid] + r9["evidence"]
        elif rid in MIXED_PREFIX:
            evidence = MIXED_PREFIX[rid] + "Carried from round 9 for the other card objects (byte-identical since the round-9 pin 1e272e5a): " + r9["evidence"]
        else:
            raise SystemExit(f"row {rid} has no round-10 decision")
        status = r9["status"]
        if status != "PASS":
            raise SystemExit(f"row {rid} is non-PASS in round 9 and was not re-verified")
        rows.append({"id": rid, "check": check, "location": location, "status": "PASS", "evidence": evidence})
    return rows


